for topic in doc['topics']:
    title,summary=nav[topic['id']]
    topic['title']=title;topic['summary']=summary
    for section in topic['sections']:
        k=(topic['id'],section['title'])
        if k in bodies: section['body']=bodies[k]
        section['title']=titles.get(section['title'],section['title'])
ru.write_text(json.dumps(doc,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print('Generated',ru,'topics',len(doc['topics']),'sections',sum(len(t['sections']) for t in doc['topics']),'translated bodies',len(bodies))
